import reactHotLoader from 'react-hot-loader/babel'
import sharedSettings from '@ctrine/babel-preset-shared'

export function createSettings() {
  let settings = sharedSettings({ treeShaking: true })

  // Plugin used to preserve state: http://gaearon.github.io/react-hot-loader/getstarted
  settings.plugins.push(reactHotLoader)

  return settings
}

export default createSettings
